/**
 * Chrome-level `PulseCard(SYNTHESIS)` on Stock Detail (pinned between `DetailHeader` and the tab
 * row, not tab content -- visible regardless of which tab is selected): the [DeepDiveLabel] date
 * line, a fixed description of what a deep dive covers (not model-generated -- the 8 topics are a
 * fixed schema, so this is static copy), and an "Open full Deep Dive" CTA row. Omitted entirely
 * when the symbol has neither a `deepAnalysisDate` nor a `nextDeepDiveTriggerDate` yet -- see
 * [deepDiveDisplayText] for the exact cold-start text rules.
 *
 * The CTA row and the tap-through to the Deep Dive screen are both gated on `deepAnalysisDate`
 * being non-null -- cold start (a computed `nextDeepDiveTriggerDate` but no deep dive has actually
 * run yet) has nothing to "open," so the card renders as informational-only ("Next: {date}", no
 * CTA, not clickable) rather than offering an action that lands on an empty screen.
 */
@Composable
fun DeepDiveCard(
    deepAnalysisDate: String?,
    nextDeepDiveTriggerDate: String?,
    onClick: () -> Unit,
    modifier: Modifier = Modifier
) {
    if (deepDiveDisplayText(deepAnalysisDate, nextDeepDiveTriggerDate) == null) return
    val hasDeepDive = deepAnalysisDate != null
    val pulseColors = LocalPulseColors.current

    PulseCard(
        style = PulseCardStyle.SYNTHESIS,
        modifier = modifier.fillMaxWidth(),
        onClick = if (hasDeepDive) onClick else null
    ) {
        Column(modifier = Modifier.padding(dimensionResource(id = R.dimen.padding_large))) {
            DeepDiveLabel(deepAnalysisDate = deepAnalysisDate, nextDeepDiveTriggerDate = nextDeepDiveTriggerDate)
            Spacer(modifier = Modifier.height(dimensionResource(id = R.dimen.padding_medium)))
            Text(
                text = stringResource(id = R.string.deep_dive_card_description),
                style = MaterialTheme.typography.bodyMedium,
                color = pulseColors.onSurfaceMuted
            )
            if (hasDeepDive) {
                Spacer(modifier = Modifier.height(dimensionResource(id = R.dimen.padding_medium)))
                Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(dimensionResource(id = R.dimen.padding_tiny))) {
                    Text(
                        text = stringResource(id = R.string.deep_dive_open_full_cta),
                        style = MaterialTheme.typography.labelLarge.copy(fontWeight = FontWeight.Bold),
                        color = pulseColors.accentPrimary
                    )
                    Icon(
                        painter = painterResource(id = R.drawable.ic_chevron_forward),
                        contentDescription = null,
                        tint = pulseColors.accentPrimary,
                        modifier = Modifier.padding(top = dimensionResource(id = R.dimen.padding_tiny))
                    )
                }
            }
        }
    }
}

